def compute_moving_average(numbers: list, window_size: int) -> list:
    """
    >>> compute_moving_average([1, 2, 3, 4, 5], 2)
    [1.5, 2.5, 3.5, 4.5]
    """
    if not numbers or window_size <= 0:
        raise ValueError("Invalid input: 'numbers' must be non-empty and 'window_size' must be positive.")
    if window_size > len(numbers):
        raise ValueError("Invalid input: 'window_size' cannot be larger than the length of 'numbers'.")

    return [
        sum(numbers[i:i + window_size]) / window_size
        for i in range(len(numbers) - window_size + 1)
    ]
