from typing import List, Dict, Any

def group_by_key(data: List[Dict[str, Any]], key: str) -> Dict[Any, List[Dict[str, Any]]]:
    """
    >>> group_by_key([{'id': 1, 'value': 'A'}, {'id': 2, 'value': 'B'}, {'id': 3, 'value': 'A'}], 'value')
    {'A': [{'id': 1, 'value': 'A'}, {'id': 3, 'value': 'A'}], 'B': [{'id': 2, 'value': 'B'}]}
    """
    if not data or not key:
        raise ValueError("Data list and key cannot be empty")

    grouped_data = {}
    for item in data:
        if key not in item:
            raise ValueError(f"Key {key} not found in item {item}")
        grouped_data.setdefault(item[key], []).append(item)

    return grouped_data
