from __future__ import annotations

def group_by_key(data: list[dict], key: str) -> dict:
    """
    Groups a list of dictionaries by the value of a given key.

    >>> group_by_key([{'id': 1, 'value': 'A'}, {'id': 2, 'value': 'B'}, {'id': 3, 'value': 'A'}], 'value')
    {'A': [{'id': 1, 'value': 'A'}, {'id': 3, 'value': 'A'}], 'B': [{'id': 2, 'value': 'B'}]}

    Complexity: O(n)
    """
    result = {}
    for item in data:
        if key not in item:
            raise ValueError(f"Key {key} not found in dictionary")
        value = item[key]
        if value not in result:
            result[value] = []
        result[value].append(item)
    return result
