    {1: [{'id': 1, 'value': 'A'}, {'id': 1, 'value': 'C'}], 2: [{'id': 2, 'value': 'B'}]}
    """
    if not data:
        raise ValueError("Input list cannot be empty")

    # NOTE: Initialize an empty dictionary to store grouped data
    grouped_data = {}

    for item in data:
        if key not in item:
            raise ValueError(f"Key '{key}' not found in one of the dictionaries")

        # NOTE: Retrieve the value associated with the given key
        value = item[key]

        # NOTE: Append the current item to the list corresponding to the value
        if value not in grouped_data:
            grouped_data[value] = []
        grouped_data[value].append(item)

    return grouped_data
